import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_conv_transpose3d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t dilation,
    int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <cstdint>

using namespace cute;

#define MAX_COUT 32

template <int K>
__global__ __launch_bounds__(512, 1)
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int B, int Cin, int Cout,
    int D, int H, int W,
    int Dout, int Hout, int Wout,
    int padding, int T, int S, int Sd, int nDt)
{
    extern __shared__ float smem[];
    const int DT = 2; // depth-dimension register-blocking factor
    int Sp = S + 2; // padded stride for the sh-dimension to reduce shared-memory bank conflicts
    int total_in = Sd * S * S;       // logical element count (used for cooperative load loop)
    int total_in_phys = Sd * Sp * S; // physical buffer size accounting for bank-conflict padding
    int total_w  = Cout * K * K * K;
    // Double-buffered shared memory: two ping-pong slots for input tile and weight slice
    float* s_in_buf[2];
    float* s_w_buf[2];
    s_in_buf[0] = smem;
    s_in_buf[1] = smem + total_in_phys;
    s_w_buf[0]  = smem + 2 * total_in_phys;
    s_w_buf[1]  = smem + 2 * total_in_phys + total_w;
    int ld = threadIdx.z;
    int lh = threadIdx.y;
    int lw = threadIdx.x;
    int wtile = blockIdx.x;
    int htile = blockIdx.y;
    int bd     = blockIdx.z;
    int batch  = bd / nDt;
    int dtile  = bd % nDt;
    int ow0 = wtile * T;
    int oh0 = htile * T;
    int od0 = dtile * T * DT;
    int ow  = ow0 + lw;
    int oh  = oh0 + lh;
    int od  = od0 + ld;
    int od2 = od0 + T + ld;
    bool validHW = (oh < Hout && ow < Wout);
    bool valid0 = validHW && (od  < Dout);
    bool valid1 = validHW && (od2 < Dout);
    int id0 = od0 + padding - (K - 1);
    int ih0 = oh0 + padding - (K - 1);
    int iw0 = ow0 + padding - (K - 1);
    // Global tensors via CuTe
    Tensor gX = make_tensor(make_gmem_ptr(x + (size_t)batch * Cin * D * H * W),
                             make_shape(Cin, D, H, W),
                             make_stride(D * H * W, H * W, W, 1));
    Tensor gW = make_tensor(make_gmem_ptr(w),
                             make_shape(Cin, Cout, K, K, K),
                             make_stride(Cout * K * K * K, K * K * K, K * K, K, 1));
    Tensor gY = make_tensor(make_gmem_ptr(y + (size_t)batch * Cout * Dout * Hout * Wout),
                             make_shape(Cout, Dout, Hout, Wout),
                             make_stride(Dout * Hout * Wout, Hout * Wout, Wout, 1));
    float acc0[MAX_COUT];
    float acc1[MAX_COUT];
    #pragma unroll
    for (int co = 0; co < MAX_COUT; ++co) { acc0[co] = 0.f; acc1[co] = 0.f; }
    int tid = threadIdx.x + threadIdx.y * T + threadIdx.z * T * T;
    int nthreads = T * T * T;
    auto load_buf = [&] (int ci, int buf) {
        Tensor sIn = make_tensor(make_smem_ptr(s_in_buf[buf]), make_shape(Sd, S, S), make_stride(Sp * S, Sp, 1));
        Tensor sW  = make_tensor(make_smem_ptr(s_w_buf[buf]), make_shape(Cout, K, K, K),
                                  make_stride(K * K * K, K * K, K, 1));
        for (int idx = tid; idx < total_in; idx += nthreads) {
            int sd = idx / (S * S);
            int rem = idx % (S * S);
            int sh = rem / S;
            int sw = rem % S;
            int id = id0 + sd;
            int ih = ih0 + sh;
            int iw = iw0 + sw;
            float val = 0.f;
            if (id >= 0 && id < D && ih >= 0 && ih < H && iw >= 0 && iw < W) {
                val = gX(ci, id, ih, iw);
            }
            sIn(sd, sh, sw) = val;
        }
        const float* w_ci = w + (size_t)ci * (size_t)total_w;
        float* sw_buf = s_w_buf[buf];
        bool vec_ok = ((total_w & 3) == 0) &&
                      (((uintptr_t)w_ci & 15u) == 0) &&
                      (((uintptr_t)sw_buf & 15u) == 0);
        if (vec_ok) {
            int total_w4 = total_w >> 2;
            const float4* w4_ptr = reinterpret_cast<const float4*>(w_ci);
            float4* sw4_ptr = reinterpret_cast<float4*>(sw_buf);
            for (int idx4 = tid; idx4 < total_w4; idx4 += nthreads) {
                sw4_ptr[idx4] = w4_ptr[idx4];
            }
        } else {
            for (int idx = tid; idx < total_w; idx += nthreads) {
                int co = idx / (K * K * K);
                int rem = idx % (K * K * K);
                int kd = rem / (K * K);
                int rem2 = rem % (K * K);
                int kh = rem2 / K;
                int kw = rem2 % K;
                sW(co, kd, kh, kw) = gW(ci, co, kd, kh, kw);
            }
        }
    };
    // Prefetch first channel's tile into buffer 0
    if (Cin > 0) {
        load_buf(0, 0);
    }
    __syncthreads();
    for (int ci = 0; ci < Cin; ++ci) {
        int cur = ci & 1;
        Tensor sIn = make_tensor(make_smem_ptr(s_in_buf[cur]), make_shape(Sd, S, S), make_stride(Sp * S, Sp, 1));
        Tensor sW  = make_tensor(make_smem_ptr(s_w_buf[cur]), make_shape(Cout, K, K, K),
                                  make_stride(K * K * K, K * K, K, 1));
        if (validHW) {
            #pragma unroll
            for (int kd = 0; kd < K; ++kd) {
                int sd = ld - kd + (K - 1);
                #pragma unroll
                for (int kh = 0; kh < K; ++kh) {
                    int sh = lh - kh + (K - 1);
                    #pragma unroll
                    for (int kw = 0; kw < K; ++kw) {
                        int sw = lw - kw + (K - 1);
                        float ival0 = sIn(sd, sh, sw);
                        float ival1 = sIn(sd + T, sh, sw);
                        #pragma unroll
                        for (int co = 0; co < MAX_COUT; ++co) {
                            if (co < Cout) {
                                float wv = sW(co, kd, kh, kw);
                                acc0[co] += ival0 * wv;
                                acc1[co] += ival1 * wv;
                            }
                        }
                    }
                }
            }
        }
        // Prefetch next channel's tile into the other buffer while compute above
        // has already consumed the current buffer, hiding load latency behind
        // the arithmetic issued for this iteration and halving barrier count.
        if (ci + 1 < Cin) {
            load_buf(ci + 1, 1 - cur);
        }
        __syncthreads();
    }
    if (valid0) {
        #pragma unroll
        for (int co = 0; co < MAX_COUT; ++co) {
            if (co < Cout) {
                float v = acc0[co];
                if (bias != nullptr) v += bias[co];
                gY(co, od, oh, ow) = v;
            }
        }
    }
    if (valid1) {
        #pragma unroll
        for (int co = 0; co < MAX_COUT; ++co) {
            if (co < Cout) {
                float v = acc1[co];
                if (bias != nullptr) v += bias[co];
                gY(co, od2, oh, ow) = v;
            }
        }
    }
}
template <int K, int COUT>
__global__ __launch_bounds__(512, 1)
__global__ void conv_transpose3d_kernel_fixedC(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int B, int Cin,
    int D, int H, int W,
    int Dout, int Hout, int Wout,
    int padding, int T, int S, int Sd, int nDt)
{
    extern __shared__ float smem[];
    const int DT = 2; // depth-dimension register-blocking factor
    int Sp = S + 2; // padded stride for the sh-dimension to reduce shared-memory bank conflicts
    int total_in = Sd * S * S;       // logical element count (used for cooperative load loop)
    int total_in_phys = Sd * Sp * S; // physical buffer size accounting for bank-conflict padding
    int total_w  = COUT * K * K * K;
    // Double-buffered shared memory: two ping-pong slots for input tile and weight slice
    float* s_in_buf[2];
    float* s_w_buf[2];
    s_in_buf[0] = smem;
    s_in_buf[1] = smem + total_in_phys;
    s_w_buf[0]  = smem + 2 * total_in_phys;
    s_w_buf[1]  = smem + 2 * total_in_phys + total_w;
    int ld = threadIdx.z;
    int lh = threadIdx.y;
    int lw = threadIdx.x;
    int wtile = blockIdx.x;
    int htile = blockIdx.y;
    int bd     = blockIdx.z;
    int batch  = bd / nDt;
    int dtile  = bd % nDt;
    int ow0 = wtile * T;
    int oh0 = htile * T;
    int od0 = dtile * T * DT;
    int ow  = ow0 + lw;
    int oh  = oh0 + lh;
    int od  = od0 + ld;
    int od2 = od0 + T + ld;
    bool validHW = (oh < Hout && ow < Wout);
    bool valid0 = validHW && (od  < Dout);
    bool valid1 = validHW && (od2 < Dout);
    int id0 = od0 + padding - (K - 1);
    int ih0 = oh0 + padding - (K - 1);
    int iw0 = ow0 + padding - (K - 1);
    // Global tensors via CuTe (Cout fixed at compile time -> tighter register allocation)
    Tensor gX = make_tensor(make_gmem_ptr(x + (size_t)batch * Cin * D * H * W),
                             make_shape(Cin, D, H, W),
                             make_stride(D * H * W, H * W, W, 1));
    Tensor gW = make_tensor(make_gmem_ptr(w),
                             make_shape(Cin, COUT, K, K, K),
                             make_stride(COUT * K * K * K, K * K * K, K * K, K, 1));
    Tensor gY = make_tensor(make_gmem_ptr(y + (size_t)batch * COUT * Dout * Hout * Wout),
                             make_shape(COUT, Dout, Hout, Wout),
                             make_stride(Dout * Hout * Wout, Hout * Wout, Wout, 1));
    float acc0[COUT];
    float acc1[COUT];
    #pragma unroll
    for (int co = 0; co < COUT; ++co) { acc0[co] = 0.f; acc1[co] = 0.f; }
    int tid = threadIdx.x + threadIdx.y * T + threadIdx.z * T * T;
    int nthreads = T * T * T;
    auto load_buf = [&] (int ci, int buf) {
        Tensor sIn = make_tensor(make_smem_ptr(s_in_buf[buf]), make_shape(Sd, S, S), make_stride(Sp * S, Sp, 1));
        Tensor sW  = make_tensor(make_smem_ptr(s_w_buf[buf]), make_shape(COUT, K, K, K),
                                  make_stride(K * K * K, K * K, K, 1));
        for (int idx = tid; idx < total_in; idx += nthreads) {
            int sd = idx / (S * S);
            int rem = idx % (S * S);
            int sh = rem / S;
            int sw = rem % S;
            int id = id0 + sd;
            int ih = ih0 + sh;
            int iw = iw0 + sw;
            float val = 0.f;
            if (id >= 0 && id < D && ih >= 0 && ih < H && iw >= 0 && iw < W) {
                val = gX(ci, id, ih, iw);
            }
            sIn(sd, sh, sw) = val;
        }
        const float* w_ci = w + (size_t)ci * (size_t)total_w;
        float* sw_buf = s_w_buf[buf];
        bool vec_ok = ((total_w & 3) == 0) &&
                      (((uintptr_t)w_ci & 15u) == 0) &&
                      (((uintptr_t)sw_buf & 15u) == 0);
        if (vec_ok) {
            int total_w4 = total_w >> 2;
            const float4* w4_ptr = reinterpret_cast<const float4*>(w_ci);
            float4* sw4_ptr = reinterpret_cast<float4*>(sw_buf);
            for (int idx4 = tid; idx4 < total_w4; idx4 += nthreads) {
                sw4_ptr[idx4] = w4_ptr[idx4];
            }
        } else {
            for (int idx = tid; idx < total_w; idx += nthreads) {
                int co = idx / (K * K * K);
                int rem = idx % (K * K * K);
                int kd = rem / (K * K);
                int rem2 = rem % (K * K);
                int kh = rem2 / K;
                int kw = rem2 % K;
                sW(co, kd, kh, kw) = gW(ci, co, kd, kh, kw);
            }
        }
    };
    if (Cin > 0) {
        load_buf(0, 0);
    }
    __syncthreads();
    for (int ci = 0; ci < Cin; ++ci) {
        int cur = ci & 1;
        Tensor sIn = make_tensor(make_smem_ptr(s_in_buf[cur]), make_shape(Sd, S, S), make_stride(Sp * S, Sp, 1));
        Tensor sW  = make_tensor(make_smem_ptr(s_w_buf[cur]), make_shape(COUT, K, K, K),
                                  make_stride(K * K * K, K * K, K, 1));
        if (validHW) {
            #pragma unroll
            for (int kd = 0; kd < K; ++kd) {
                int sd = ld - kd + (K - 1);
                #pragma unroll
                for (int kh = 0; kh < K; ++kh) {
                    int sh = lh - kh + (K - 1);
                    #pragma unroll
                    for (int kw = 0; kw < K; ++kw) {
                        int sw = lw - kw + (K - 1);
                        float ival0 = sIn(sd, sh, sw);
                        float ival1 = sIn(sd + T, sh, sw);
                        #pragma unroll
                        for (int co = 0; co < COUT; ++co) {
                            float wv = sW(co, kd, kh, kw);
                            acc0[co] += ival0 * wv;
                            acc1[co] += ival1 * wv;
                        }
                    }
                }
            }
        }
        // Prefetch next channel's tile into the other buffer while compute above
        // has already consumed the current buffer, hiding load latency behind
        // the arithmetic issued for this iteration and halving barrier count.
        if (ci + 1 < Cin) {
            load_buf(ci + 1, 1 - cur);
        }
        __syncthreads();
    }
    if (valid0) {
        #pragma unroll
        for (int co = 0; co < COUT; ++co) {
            float v = acc0[co];
            if (bias != nullptr) v += bias[co];
            gY(co, od, oh, ow) = v;
        }
    }
    if (valid1) {
        #pragma unroll
        for (int co = 0; co < COUT; ++co) {
            float v = acc1[co];
            if (bias != nullptr) v += bias[co];
            gY(co, od2, oh, ow) = v;
        }
    }
}
torch::Tensor cute_conv_transpose3d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t dilation,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only float32 supported");
    TORCH_CHECK(x.dim() == 5, "x must be 5D (B,Cin,D,H,W)");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    int B    = (int)x_c.size(0);
    int Cin  = (int)x_c.size(1);
    int D    = (int)x_c.size(2);
    int H    = (int)x_c.size(3);
    int W    = (int)x_c.size(4);
    int Cout = (int)w_c.size(1);
    int K    = (int)w_c.size(2);
    int Dout = (int)((D - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1);
    int Hout = (int)((H - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1);
    int Wout = (int)((W - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1);
    auto y = torch::zeros({B, Cout, Dout, Hout, Wout}, x.options());
    bool has_bias = bias.defined() && bias.numel() > 0;
    bool fast_path = (stride == 1 && dilation == 1 && groups == 1 && Cout <= MAX_COUT && K == 3);
    if (fast_path) {
        const int T = 8;
        const int DT = 2; // depth-dimension register-blocking factor: each thread computes 2 outputs along D
        int S  = T + K - 1;
        int Sd = T * DT + K - 1;
        dim3 block(T, T, T);
        int nDt = (Dout + T * DT - 1) / (T * DT);
        int nHt = (Hout + T - 1) / T;
        int nWt = (Wout + T - 1) / T;
        dim3 grid(nWt, nHt, (unsigned int)(B * nDt));
        size_t smem_bytes = 2 * ((size_t)Sd * (S + 2) * S * sizeof(float) +
                                 (size_t)Cout * K * K * K * sizeof(float));
        const float* bias_ptr = has_bias ? bias.contiguous().data_ptr<float>() : nullptr;
        cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
        // Dispatch to a Cout-templated kernel for common exact channel counts.
        // Fixing Cout at compile time lets the compiler size the accumulator
        // register arrays exactly (no wasted MAX_COUT-sized registers/branches),
        // improving register-blocking efficiency for these shapes.
        if (Cout == 16) {
            conv_transpose3d_kernel_fixedC<3, 16><<<grid, block, smem_bytes, stream>>>(
                x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
                B, Cin, D, H, W, Dout, Hout, Wout, (int)padding, T, S, Sd, nDt);
        } else if (Cout == 24) {
            conv_transpose3d_kernel_fixedC<3, 24><<<grid, block, smem_bytes, stream>>>(
                x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
                B, Cin, D, H, W, Dout, Hout, Wout, (int)padding, T, S, Sd, nDt);
        } else if (Cout == 32) {
            conv_transpose3d_kernel_fixedC<3, 32><<<grid, block, smem_bytes, stream>>>(
                x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
                B, Cin, D, H, W, Dout, Hout, Wout, (int)padding, T, S, Sd, nDt);
        } else {
            conv_transpose3d_kernel<3><<<grid, block, smem_bytes, stream>>>(
                x_c.data_ptr<float>(),
                w_c.data_ptr<float>(),
                bias_ptr,
                y.data_ptr<float>(),
                B, Cin, Cout,
                D, H, W,
                Dout, Hout, Wout,
                (int)padding, T, S, Sd, nDt);
        }
        TORCH_CHECK(cudaGetLastError() == cudaSuccess, "conv_transpose3d_kernel launch failed");
    } else {
        // Fallback for unsupported configurations
        c10::optional<torch::Tensor> bias_opt = has_bias ? c10::optional<torch::Tensor>(bias) : c10::nullopt;
        y = at::conv_transpose3d(x, weight, bias_opt, stride, padding, output_padding, groups, dilation);
    }
    return y;
}
"""

cute_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv_transpose3d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "-I/workspace/cutegen_test/cutegen/cutlass/include"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution using a custom CuTe-based CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0,
                 output_padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Keep an nn.ConvTranspose3d purely as a parameter container (weight/bias),
        # but forward() uses our custom CUDA/CuTe kernel instead of its built-in op.
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, (kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            dilation=dilation, groups=groups, bias=bias)

        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        if bias is None:
            bias_t = torch.empty(0, device=x.device, dtype=x.dtype)
        else:
            bias_t = bias

        x = x.contiguous()
        return self._ext.cute_conv_transpose3d(
            x, weight, bias_t,
            self.stride, self.padding, self.output_padding, self.dilation, self.groups)


