class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution using a custom CuTe-based CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0,
                 output_padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Keep an nn.ConvTranspose3d purely as a parameter container (weight/bias),
        # but forward() uses our custom CUDA/CuTe kernel instead of its built-in op.
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, (kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            dilation=dilation, groups=groups, bias=bias)

        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        if bias is None:
            bias_t = torch.empty(0, device=x.device, dtype=x.dtype)
        else:
            bias_t = bias

        x = x.contiguous()
        return self._ext.cute_conv_transpose3d(
            x, weight, bias_t,
            self.stride, self.padding, self.output_padding, self.dilation, self.groups)


